+          }
+          .width('100%')
+          .height(44)
+          .justifyContent(FlexAlign.Center)
+        }
+      }
+      .width('100%')
+      .height('100%')
+
+      // 复用池状态指示条（调试观测设施）
+      Text(this.poolStats)
+        .fontSize(12)
+        .fontColor('#E6FFFFFF')
+        .padding({ left: 14, right: 14, top: 6, bottom: 6 })
+        .borderRadius(14)
+        .backgroundColor('#66000000')
